import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { MODELS } from "../lib/models";

// Pins the TS model port to the Python source. The fixture is generated by
// prelim_pred/export_model_fixture.py from the SAME params the frontend uses, so a
// mismatch here means the two implementations have drifted (regenerate + investigate).
type Case = { dr: number; probs: [number, number, number] };
type Fixture = Record<string, { params: Record<string, number>; cases: Case[] }>;

const fixturePath = fileURLToPath(
  new URL("./fixtures/model_probs.json", import.meta.url),
);
const fixture = JSON.parse(readFileSync(fixturePath, "utf-8")) as Fixture;

describe("TS outcome models reproduce the Python reference", () => {
  for (const [id, { params, cases }] of Object.entries(fixture)) {
    it(`${id} matches python at every dr`, () => {
      for (const { dr, probs } of cases) {
        const got = MODELS[id](dr, params);
        for (let k = 0; k < 3; k++) {
          expect(got[k]).toBeCloseTo(probs[k], 9);
        }
        expect(got[0] + got[1] + got[2]).toBeCloseTo(1, 12);
      }
    });
  }
});
